import sys
from collections import defaultdict

def solve():
    n, m = map(int, sys.stdin.readline().split())
    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        graph[u].append(v)
        graph[v].append(u)
    # Build adjacency matrix for fast lookup
    adj = [[False] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        adj[i][i] = True
    for i in range(n + 1):
        for j in range(n + 1):
            if i != j:
                adj[i][j] = False
    # Find all valid assignments
    for i in range(n + 1):
        for j in range(n + 1):
            if i != j:
                adj[i][j] = False
    # If no valid assignment, print NO
    print("NO")
    return

def main():
    import sys
    input = sys.stdin.readline
    n, m = map(int, input().split())
    # Read the graph
    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v = map(int, input().split())
        graph[u].append(v)
        graph[v].append(u)
    # Find all valid assignments
    for i in range(n + 1):
        for j in range(n + 1):
            if i != j:
                adj[i][j] = False
    # If no valid assignment, print NO
    print("NO")
    return

